"use client";

import FullCalendar, { type DatesSetInfo } from "@fullcalendar/react";
import dayGridPlugin from "@fullcalendar/react/daygrid";
import listPlugin from "@fullcalendar/react/list";
import classicTheme from "@fullcalendar/react/themes/classic";
import timeGridPlugin from "@fullcalendar/react/timegrid";
import { PlusIcon, RefreshCwIcon, SettingsIcon } from "lucide-react";
import { useCallback, useMemo, useState, useSyncExternalStore } from "react";
import type { ComponentType } from "react";

import { Link, type LinkProps } from "@/components/link";
import {
  getReservationLabels,
  type ReservationLabels,
} from "@/components/plugins/reservations/labels";
import {
  catalog,
  loadReservationCalendar,
  localDate,
} from "@/components/plugins/reservations/model";
import { BookingForm, RescheduleDialog } from "@/components/plugins/reservations/public";
import type {
  ReservationAdminRecord,
  ReservationRange,
  ReservationStatus,
  ReservationsAdminClient,
  ReservationsPublicClient,
} from "@/components/plugins/reservations/types";
import {
  buttonClass,
  primaryClass,
  fieldClass,
  pageClass,
  Field,
  ErrorNotice,
  Modal,
  ReservationSummary,
  useReservationAction,
  useReservationLoad,
} from "@/components/plugins/reservations/ui";
import { ReservationYearView } from "@/components/plugins/reservations/year";
import { cn } from "@/components/utils/cn";

import "./calendar.css";

const subscribe = () => () => {};
const mobileSnapshot = () => window.matchMedia("(max-width: 639px)").matches;
function subscribeMobile(callback: () => void) {
  const query = window.matchMedia("(max-width: 639px)");
  query.addEventListener("change", callback);
  return () => query.removeEventListener("change", callback);
}

export interface ReservationsCalendarProps {
  client: ReservationsAdminClient;
  locale?: string;
  labels?: Partial<ReservationLabels>;
  initialDate?: string;
  settingsHref?: string;
  canManage?: boolean;
  className?: string;
  linkComponent?: ComponentType<LinkProps>;
}

export function ReservationsCalendar({
  client,
  locale = "en",
  labels: overrides,
  initialDate,
  settingsHref,
  canManage = true,
  className,
  linkComponent: HostLink = Link,
}: ReservationsCalendarProps) {
  const mounted = useSyncExternalStore(
    subscribe,
    () => true,
    () => false,
  );
  const mobile = useSyncExternalStore(subscribeMobile, mobileSnapshot, () => false);
  const [view, setView] = useState("");
  const [range, setRange] = useState<ReservationRange>(() => {
    const from = initialDate ? new Date(`${initialDate}T00:00:00Z`) : new Date();
    return { from: from.toISOString(), to: new Date(from.getTime() + 7 * 86400000).toISOString() };
  });
  const [selected, setSelected] = useState<ReservationAdminRecord>();
  const [dialog, setDialog] = useState<"new" | "move" | "cancelled" | "rejected" | "link">();
  const load = useCallback(() => client.configuration(), [client]);
  const config = useReservationLoad(load);
  const labels = getReservationLabels(overrides, config.value?.mode);
  const timeZone = config.value?.settings.timeZone ?? "UTC";
  const loadBookings = useCallback(() => loadReservationCalendar(client, range), [client, range]);
  const data = useReservationLoad(loadBookings);
  const action = useReservationAction();
  const refresh = () => {
    data.reload();
    setSelected(undefined);
    setDialog(undefined);
  };
  const datesSet = useCallback((info: DatesSetInfo) => {
    setView(info.view.type);
    setRange((r) => {
      const from = info.start.toISOString(),
        to = info.end.toISOString();
      return r.from === from && r.to === to ? r : { ...r, from, to };
    });
  }, []);
  const staffClient = useMemo<ReservationsPublicClient>(
    () => ({
      catalog: async () => catalog(await client.configuration()),
      availability: (q) => client.availability(q),
      book: (input) => client.book(input),
    }),
    [client],
  );
  const moveAvailability = useCallback(
    (query: { date: string; resourceId?: string; departureDate?: string }) =>
      client.availability({
        ...query,
        serviceId: selected?.serviceId ?? "",
        reservationId: selected?.id,
      }),
    [client, selected?.id, selected?.serviceId],
  );
  const moveSave = useCallback(
    (input: Parameters<ReservationsAdminClient["reschedule"]>[1]) =>
      client.reschedule(selected?.id ?? "", input),
    [client, selected?.id],
  );
  return (
    <section className={cn(pageClass, className)}>
      <div className="flex flex-wrap items-center justify-between gap-3">
        <h1 className="font-serif text-3xl font-semibold">{labels.calendar}</h1>
        <div className="flex flex-wrap gap-2">
          <button className={buttonClass} onClick={refresh}>
            <RefreshCwIcon className="size-4 shrink-0" aria-hidden="true" />
            {labels.refresh}
          </button>
          {settingsHref && (
            <HostLink className={buttonClass} href={settingsHref}>
              <SettingsIcon className="size-4 shrink-0" aria-hidden="true" />
              {labels.settings}
            </HostLink>
          )}
          {canManage && (
            <button
              className={primaryClass}
              disabled={!config.value?.services.some((s) => s.active && !s.archived)}
              onClick={() => setDialog("new")}
            >
              <PlusIcon className="size-4 shrink-0" aria-hidden="true" />
              {labels.newBooking}
            </button>
          )}
        </div>
      </div>
      <ErrorNotice error={config.error ?? data.error ?? action.error} labels={labels} />
      {config.value && (
        <>
          <div className="grid gap-3 sm:grid-cols-3">
            <Field label={labels.resource}>
              <select
                className={fieldClass}
                value={range.resourceId ?? ""}
                onChange={(e) => setRange({ ...range, resourceId: e.target.value || undefined })}
              >
                <option value="">{labels.all}</option>
                {config.value.resources.map((r) => (
                  <option key={r.id} value={r.id}>
                    {r.name}
                  </option>
                ))}
              </select>
            </Field>
            <Field label={labels.service}>
              <select
                className={fieldClass}
                value={range.serviceId ?? ""}
                onChange={(e) => setRange({ ...range, serviceId: e.target.value || undefined })}
              >
                <option value="">{labels.all}</option>
                {config.value.services.map((s) => (
                  <option key={s.id} value={s.id}>
                    {s.name}
                  </option>
                ))}
              </select>
            </Field>
            <Field label={labels.status}>
              <select
                className={fieldClass}
                value={range.status ?? ""}
                onChange={(e) =>
                  setRange({
                    ...range,
                    status: e.target.value ? (e.target.value as ReservationStatus) : undefined,
                  })
                }
              >
                <option value="">{labels.all}</option>
                {(["pending", "confirmed", "rejected", "cancelled"] as const).map((s) => (
                  <option key={s} value={s}>
                    {labels[s]}
                  </option>
                ))}
              </select>
            </Field>
          </div>
          <p className="text-sm text-muted-foreground">
            {labels.timeZone}: {config.value.settings.timeZone}
          </p>
        </>
      )}
      {(!data.value || !config.value) && !data.error && !config.error && (
        <output className="block">{labels.loading}</output>
      )}
      {mounted && config.value && (
        <div className="reservations-calendar min-w-0 overflow-x-auto rounded-xl border border-border p-3">
          <FullCalendar
            plugins={[classicTheme, dayGridPlugin, timeGridPlugin, listPlugin]}
            initialView={mobile ? "listWeek" : "timeGridWeek"}
            initialDate={initialDate}
            locale={locale}
            timeZone={config.value.settings.timeZone}
            headerToolbar={{
              start: "prev,next today",
              center: "title",
              end: "reservationsYear,dayGridMonth,timeGridWeek,timeGridDay,listWeek",
            }}
            views={{
              reservationsYear: {
                duration: { months: 12 },
                dateAlignment: "month",
                dateIncrement: { years: 1 },
                titleFormat: { month: "short", year: "numeric" },
                content: (info) =>
                  data.value ? (
                    <ReservationYearView
                      key={info.view.currentStart.toISOString()}
                      start={localDate(info.view.currentStart.toISOString(), timeZone)}
                      reservations={data.value}
                      timeZone={timeZone}
                      locale={locale}
                      labels={labels}
                      onSelectDate={(date) => info.view.calendar.changeView("timeGridDay", date)}
                    />
                  ) : null,
              },
            }}
            toolbarClass="flex flex-wrap items-center justify-between gap-3 mb-4"
            toolbarSectionClass="flex min-w-0 max-w-full flex-wrap items-center gap-2"
            buttonGroupClass="flex min-w-0 max-w-full flex-wrap items-center gap-2"
            toolbarTitleClass="max-w-full text-lg font-semibold whitespace-normal"
            viewHint={(text) => text}
            buttons={{
              reservationsYear: { text: labels.year, hint: labels.year },
              dayGridMonth: { text: labels.month, hint: labels.month },
              timeGridWeek: { text: labels.week, hint: labels.week },
              timeGridDay: { text: labels.day, hint: labels.day },
              listWeek: { text: labels.agenda, hint: labels.agenda },
            }}
            buttonClass={cn(
              buttonClass,
              "aria-selected:bg-primary aria-selected:text-primary-foreground",
            )}
            todayText={labels.today}
            monthText={labels.month}
            weekTextLong={labels.week}
            dayText={labels.day}
            listText={labels.agenda}
            prevHint={labels.previous}
            nextHint={labels.next}
            todayHint={labels.today}
            height={mobile || view === "reservationsYear" ? "auto" : 640}
            firstDay={1}
            allDaySlot={false}
            slotMinTime="00:00:00"
            slotMaxTime="24:00:00"
            scrollTime="08:00:00"
            editable={false}
            eventInteractive
            noEventsText={labels.emptyCalendar}
            datesSet={datesSet}
            eventClass={(info) =>
              cn(
                `reservation-${String(info.event.extendedProps.status)}`,
                "rounded-md border px-1 text-xs focus-visible:outline-2 focus-visible:outline-ring",
                info.event.extendedProps.status === "pending"
                  ? "bg-status-pending text-status-pending-foreground"
                  : info.event.extendedProps.status === "confirmed"
                    ? "bg-status-success text-status-success-foreground"
                    : "bg-status-canceled text-status-canceled-foreground",
              )
            }
            listItemEventTitleClass="whitespace-normal break-words p-2"
            listDayHeaderInnerClass="flex flex-wrap items-center justify-between gap-1 p-2 text-sm"
            events={(data.value ?? []).map((r) => ({
              id: r.id,
              start: r.startsAt,
              end: r.endsAt,
              title: `${r.customer.name} · ${r.serviceName} · ${r.resourceName} · ${labels[r.status]}${r.outsideHours ? ` · ${labels.outsideHours}` : ""}`,
              extendedProps: { status: r.status },
            }))}
            eventClick={(info) => setSelected(data.value?.find((r) => r.id === info.event.id))}
          />
        </div>
      )}
      {dialog === "new" && config.value && (
        <Modal
          title={labels.newBooking}
          description={labels.timeZone + ": " + config.value.settings.timeZone}
          onClose={() => setDialog(undefined)}
        >
          <BookingForm
            staff
            client={staffClient}
            catalog={catalog(config.value)}
            locale={locale}
            labels={labels}
            initialDate={initialDate}
            onBooked={refresh}
          />
        </Modal>
      )}
      {selected && !dialog && (
        <Modal
          title={selected.customer.name}
          description={
            selected.customer.email +
            (selected.customer.phone ? ` · ${selected.customer.phone}` : "")
          }
          onClose={() => setSelected(undefined)}
          busy={action.busy}
        >
          <ReservationSummary reservation={selected} locale={locale} labels={labels} />
          <ErrorNotice error={action.error} labels={labels} />
          {selected.outsideHours && (
            <output className="block text-sm text-destructive">{labels.outsideHours}</output>
          )}
          {selected.emailFailed && (
            <output className="block text-sm text-destructive">{labels.emailFailed}</output>
          )}
          <div className="flex flex-wrap gap-2">
            {canManage && (
              <>
                {selected.status === "pending" && (
                  <>
                    <button
                      className={primaryClass}
                      disabled={action.busy}
                      onClick={() => {
                        void action.run(async () => {
                          await client.setStatus(selected.id, selected.version, "confirmed");
                          refresh();
                        });
                      }}
                    >
                      {labels.approve}
                    </button>
                    <button className={buttonClass} onClick={() => setDialog("rejected")}>
                      {labels.reject}
                    </button>
                  </>
                )}
                {(selected.status === "pending" || selected.status === "confirmed") && (
                  <>
                    <button className={buttonClass} onClick={() => setDialog("move")}>
                      {labels.reschedule}
                    </button>
                    <button className={buttonClass} onClick={() => setDialog("cancelled")}>
                      {labels.cancel}
                    </button>
                  </>
                )}
                {selected.emailFailed && (
                  <button
                    className={buttonClass}
                    disabled={action.busy}
                    onClick={() => {
                      void action.run(async () => {
                        await client.retryEmail(selected.id);
                        refresh();
                      });
                    }}
                  >
                    {labels.retryEmail}
                  </button>
                )}
                <button className={buttonClass} onClick={() => setDialog("link")}>
                  {labels.revokeLink}
                </button>
              </>
            )}
            <button className={buttonClass} onClick={() => setSelected(undefined)}>
              {labels.close}
            </button>
          </div>
        </Modal>
      )}
      {selected && (dialog === "cancelled" || dialog === "rejected" || dialog === "link") && (
        <Modal
          title={
            dialog === "link"
              ? labels.revokeLink
              : dialog === "cancelled"
                ? labels.cancel
                : labels.reject
          }
          description={
            dialog === "link"
              ? labels.revokeConfirm
              : dialog === "cancelled"
                ? labels.cancelConfirm
                : labels.rejectConfirm
          }
          onClose={() => setDialog(undefined)}
          busy={action.busy}
        >
          <ErrorNotice error={action.error} labels={labels} />
          <div className="flex gap-2">
            <button
              className={buttonClass}
              disabled={action.busy}
              onClick={() => setDialog(undefined)}
            >
              {labels.back}
            </button>
            <button
              className={primaryClass}
              disabled={action.busy}
              onClick={() => {
                void action.run(async () => {
                  if (dialog === "link") await client.revokeLink(selected.id, selected.version);
                  else await client.setStatus(selected.id, selected.version, dialog);
                  refresh();
                });
              }}
            >
              {dialog === "link"
                ? labels.revokeLink
                : dialog === "cancelled"
                  ? labels.cancel
                  : labels.reject}
            </button>
          </div>
        </Modal>
      )}
      {selected && dialog === "move" && (
        <RescheduleDialog
          reservation={selected}
          timeZone={config.value?.settings.timeZone ?? selected.timeZone}
          resources={
            config.value?.resources.filter(
              (r) =>
                r.active &&
                !r.archived &&
                config.value?.services
                  .find((s) => s.id === selected.serviceId)
                  ?.resourceIds.includes(r.id),
            ) ?? []
          }
          locale={locale}
          labels={labels}
          availability={moveAvailability}
          onSave={moveSave}
          onSaved={refresh}
          onClose={() => setDialog(undefined)}
        />
      )}
    </section>
  );
}

@import "@fullcalendar/react/skeleton.css" layer(components);
@import "@fullcalendar/react/themes/classic/theme.css" layer(components);

.reservations-calendar {
  --fc-classic-background: var(--background);
  --fc-classic-foreground: var(--foreground);
  --fc-classic-border: var(--border);
  --fc-classic-primary: var(--primary);
  --fc-classic-muted: var(--muted);
  --fc-classic-muted-foreground: var(--muted-foreground);
  --fc-classic-faint: var(--muted);
  --fc-classic-faint-foreground: var(--muted-foreground);
  --fc-classic-strong: var(--accent);
  --fc-classic-strong-border: var(--border);
  --fc-classic-button: var(--background);
  --fc-classic-button-foreground: var(--foreground);
  --fc-classic-button-border: var(--border);
  --fc-classic-button-outline: var(--ring);
  --fc-classic-button-strong: var(--accent);
  --fc-classic-button-strong-border: var(--border);
  --fc-classic-ring-color: var(--ring);
  --fc-classic-today: var(--accent);
  --fc-classic-highlight: var(--accent);
  --fc-classic-now: var(--primary);
  --fc-classic-background-event-opacity: 20%;
  --fc-classic-background-event-foreground-opacity: 100%;
  --fc-classic-small-dot-width: 6px;
  --fc-classic-large-dot-width: 10px;
  --fc-event-color: var(--primary);
  --fc-event-contrast-color: var(--primary-foreground);
}
.reservations-calendar .reservation-pending {
  --fc-event-color: var(--status-pending);
  --fc-event-contrast-color: var(--status-pending-foreground);
}
.reservations-calendar .reservation-confirmed {
  --fc-event-color: var(--status-success);
  --fc-event-contrast-color: var(--status-success-foreground);
}
.reservations-calendar .reservation-cancelled,
.reservations-calendar .reservation-rejected {
  --fc-event-color: var(--status-canceled);
  --fc-event-contrast-color: var(--status-canceled-foreground);
}

export {
  ReservationBookingPage,
  ReservationManagePage,
  type ReservationBookingPageProps,
  type ReservationManagePageProps,
} from "@/components/plugins/reservations/public";
export {
  ReservationsCalendar,
  type ReservationsCalendarProps,
} from "@/components/plugins/reservations/admin";
export {
  ReservationSettingsPage,
  type ReservationSettingsPageProps,
} from "@/components/plugins/reservations/settings";
export {
  reservationLabels,
  type ReservationLabels,
} from "@/components/plugins/reservations/labels";
export {
  reservationPolicyDefaults,
  reservationStayPolicyDefaults,
} from "@/components/plugins/reservations/model";
export { ReservationError } from "@/components/plugins/reservations/types";
export type * from "@/components/plugins/reservations/types";

import { Temporal } from "temporal-polyfill";
import { z } from "zod";

import {
  ReservationError,
  type Reservation,
  type ReservationAvailabilityQuery,
  type ReservationBookingInput,
  type ReservationConfiguration,
  type ReservationHours,
  type ReservationPolicy,
  type ReservationCommonPolicy,
  type ReservationMode,
  type ReservationRange,
  type ReservationAdminRecord,
  type ReservationResource,
  type ReservationService,
  type ReservationSlot,
  type ReservationsAdminClient,
} from "@/components/plugins/reservations/types";

export const reservationPolicyDefaults = {
  bufferBeforeMinutes: 0,
  bufferAfterMinutes: 0,
  cancellationMinutes: 1440,
  approval: "automatic",
  noticeMinutes: 60,
  horizonDays: 90,
  intervalMinutes: 15,
} satisfies ReservationCommonPolicy;

const id = z.string().uuid();
const minutes = z.number().int().min(0).max(525600);
const commonPolicySchema = z.object({
  bufferBeforeMinutes: minutes.max(1440),
  bufferAfterMinutes: minutes.max(1440),
  cancellationMinutes: minutes,
  approval: z.enum(["automatic", "manual"]),
  noticeMinutes: minutes,
  horizonDays: z.number().int().min(1).max(365),
  intervalMinutes: z.number().int().min(1).max(1440),
});
const time = z.string().regex(/^(?:[01]\d|2[0-3]):[0-5]\d$/);
const appointmentPolicySchema = commonPolicySchema.extend({
  mode: z.literal("appointment").default("appointment"),
  durationMinutes: z.number().int().min(1).max(1440),
});
const stayPolicySchema = commonPolicySchema
  .extend({
    mode: z.literal("stay"),
    arrivalStart: time,
    arrivalEnd: time,
    checkoutTime: time,
    minNights: z.number().int().min(1).max(365),
    maxNights: z.number().int().min(1).max(365),
  })
  .refine((v) => v.arrivalStart < v.arrivalEnd && v.minNights <= v.maxNights);
export const policySchema = z.union([appointmentPolicySchema, stayPolicySchema]);
const serviceFields = {
  id,
  version: z.number().int().nonnegative(),
  name: z.string().trim().min(1).max(120),
  description: z.string().trim().max(2000),
  resourceIds: z.array(id).max(100),
  active: z.boolean(),
  archived: z.boolean(),
};
export const serviceSchema = z
  .union([
    appointmentPolicySchema.extend(serviceFields),
    stayPolicySchema.safeExtend(serviceFields),
  ])
  .refine((v) => new Set(v.resourceIds).size === v.resourceIds.length);
export const reservationStayPolicyDefaults = {
  ...reservationPolicyDefaults,
  mode: "stay" as const,
  minNights: 1,
  maxNights: 30,
};
const hours = z
  .array(z.object({ start: time, end: z.union([time, z.literal("24:00")]) }))
  .max(12)
  .refine((v) => {
    const sorted = [...v].sort((a, b) => a.start.localeCompare(b.start));
    return sorted.every((h, i) => h.start < h.end && (!i || sorted[i - 1].end <= h.start));
  });
export const dateSchema = z
  .string()
  .regex(/^\d{4}-\d{2}-\d{2}$/)
  .refine((value) => {
    try {
      return Temporal.PlainDate.from(value).toString() === value;
    } catch {
      return false;
    }
  });
export const resourceSchema = z.object({
  id,
  version: z.number().int().nonnegative(),
  name: z.string().trim().min(1).max(120),
  active: z.boolean(),
  archived: z.boolean(),
  weeklyHours: z.record(z.string().regex(/^[1-7]$/), hours),
  exceptions: z.record(dateSchema, hours).refine((v) => Object.keys(v).length <= 730),
  blockedDates: z
    .array(z.object({ from: dateSchema, through: dateSchema }).refine((v) => v.from <= v.through))
    .max(730)
    .optional(),
});
export const settingsSchema = z.object({
  version: z.number().int().nonnegative(),
  publicBookingEnabled: z.boolean(),
  timeZone: z
    .string()
    .max(100)
    .refine((value) => {
      try {
        new Intl.DateTimeFormat("en", { timeZone: value });
        return !/^[+-]/.test(value);
      } catch {
        return false;
      }
    }),
});
export const instantSchema = z
  .string()
  .datetime({ offset: true })
  .transform((v) => new Date(v).toISOString());
export const customerSchema = z.object({
  name: z.string().trim().min(1).max(120),
  email: z
    .string()
    .trim()
    .email()
    .max(254)
    .transform((v) => v.toLowerCase()),
  phone: z.string().trim().max(40),
});
export const bookingSchema = z.object({
  requestId: id,
  serviceId: id,
  resourceId: id.optional(),
  startsAt: instantSchema,
  departureDate: dateSchema.optional(),
  customer: customerSchema,
  locale: z
    .string()
    .regex(/^[a-z]{2,3}(?:-[a-zA-Z0-9]{2,8})*$/)
    .max(35)
    .refine((value) => {
      try {
        return Intl.getCanonicalLocales(value).length === 1;
      } catch {
        return false;
      }
    }),
});
export const availabilitySchema = z.object({
  serviceId: id,
  resourceId: id.optional(),
  date: dateSchema,
  departureDate: dateSchema.optional(),
});
export const moveSchema = z.object({
  version: z.number().int().positive(),
  startsAt: instantSchema,
  departureDate: dateSchema.optional(),
  resourceId: id.optional(),
});
export const rangeSchema = z
  .object({
    from: instantSchema,
    to: instantSchema,
    resourceId: id.optional(),
    serviceId: id.optional(),
    status: z.enum(["pending", "confirmed", "cancelled", "rejected"]).optional(),
  })
  .refine(
    (v) =>
      Date.parse(v.to) > Date.parse(v.from) &&
      Date.parse(v.to) - Date.parse(v.from) <= 43 * 86400000,
  );

/** Keep the server's bounded list contract when displaying a whole year. */
export async function loadReservationCalendar(
  client: Pick<ReservationsAdminClient, "list">,
  range: ReservationRange,
): Promise<ReservationAdminRecord[]> {
  const from = Date.parse(range.from),
    to = Date.parse(range.to);
  if (!Number.isFinite(from) || !Number.isFinite(to) || to <= from || to - from > 367 * 86400000)
    throw new ReservationError("INVALID");
  if (to - from <= 43 * 86400000) return client.list(range);
  const queries: ReservationRange[] = [];
  for (let start = from; start < to; start += 42 * 86400000) {
    queries.push({
      ...range,
      from: new Date(start).toISOString(),
      to: new Date(Math.min(start + 42 * 86400000, to)).toISOString(),
    });
  }
  const pages = await Promise.all(queries.map((query) => client.list(query)));
  const unique = new Map<string, ReservationAdminRecord>();
  for (const reservation of pages.flat()) {
    if ((unique.get(reservation.id)?.version ?? 0) < reservation.version)
      unique.set(reservation.id, reservation);
  }
  return [...unique.values()];
}

export function parseReservationInput<T>(schema: z.ZodType<T>, input: unknown): T {
  const result = schema.safeParse(input);
  if (!result.success) throw new ReservationError("INVALID");
  return result.data;
}
export const parseReservationId = (input: unknown) => parseReservationInput(id, input);
export const activeReservation = (r: Reservation) =>
  r.status === "pending" || r.status === "confirmed";
export const overlaps = (a: string, b: string, c: string, d: string) => a < d && c < b;
export const addMinutes = (iso: string, value: number) =>
  new Date(Date.parse(iso) + value * 60000).toISOString();
export const localDate = (iso: string, zone: string) =>
  Temporal.Instant.from(iso).toZonedDateTimeISO(zone).toPlainDate().toString();

export function hoursFor(resource: ReservationResource, date: string): ReservationHours[] {
  return (
    resource.exceptions[date] ??
    resource.weeklyHours[String(Temporal.PlainDate.from(date).dayOfWeek)] ??
    []
  );
}

/** Return both occurrences of repeated wall times, and none for nonexistent times. */
function wallInstants(date: string, time: string, zone: string): string[] {
  const day = Temporal.PlainDate.from(date);
  const plain =
    time === "24:00" ? day.add({ days: 1 }).toPlainDateTime("00:00") : day.toPlainDateTime(time);
  const values = ["earlier", "later"] as const;
  return [
    ...new Set(
      values.flatMap((disambiguation) => {
        const zoned = plain.toZonedDateTime(zone, { disambiguation });
        return zoned.toPlainDateTime().equals(plain)
          ? [new Date(Number(zoned.epochMilliseconds)).toISOString()]
          : [];
      }),
    ),
  ];
}

function workingWindows(resource: ReservationResource, date: string, zone: string) {
  return hoursFor(resource, date).flatMap((h) => {
    // Schedule boundaries in a DST gap close that interval rather than silently moving it.
    const starts = wallInstants(date, h.start, zone).sort();
    const ends = wallInstants(date, h.end, zone).sort();
    return starts.length && ends.length ? [{ start: starts[0], end: ends[ends.length - 1] }] : [];
  });
}

export function fitsHours(
  resource: ReservationResource,
  start: string,
  end: string,
  zone: string,
): boolean {
  return workingWindows(resource, localDate(start, zone), zone).some(
    (w) => start >= w.start && end <= w.end,
  );
}

export function stayNights(arrival: string, departure: string): number {
  return Temporal.PlainDate.from(arrival).until(Temporal.PlainDate.from(departure)).days;
}

export function fitsResource(
  resource: ReservationResource,
  start: string,
  end: string,
  zone: string,
  mode: ReservationMode = "appointment",
): boolean {
  if (mode === "appointment") return fitsHours(resource, start, end, zone);
  return !(resource.blockedDates ?? []).some((block) => {
    const from = Temporal.PlainDate.from(block.from)
      .toZonedDateTime(zone)
      .toInstant()
      .toString({ fractionalSecondDigits: 3 });
    const to = Temporal.PlainDate.from(block.through)
      .add({ days: 1 })
      .toZonedDateTime(zone)
      .toInstant()
      .toString({ fractionalSecondDigits: 3 });
    return overlaps(start, end, from, to);
  });
}

function reservationEnd(
  policy: ReservationPolicy,
  start: string,
  departure: string | undefined,
  zone: string,
) {
  if (policy.mode !== "stay") {
    if (departure !== undefined) throw new ReservationError("INVALID");
    return addMinutes(start, policy.durationMinutes);
  }
  if (!departure || !dateSchema.safeParse(departure).success) throw new ReservationError("INVALID");
  const nights = stayNights(localDate(start, zone), departure);
  if (nights < policy.minNights || nights > policy.maxNights) throw new ReservationError("INVALID");
  return wallInstants(departure, policy.checkoutTime, zone).sort().at(-1);
}

export function canCustomerChange(reservation: Reservation, now: string) {
  return (
    activeReservation(reservation) &&
    now < reservation.cancellationDeadline &&
    now < reservation.startsAt
  );
}

export function catalog(configuration: ReservationConfiguration) {
  const resources = configuration.resources.filter((r) => r.active && !r.archived);
  const services = configuration.services
    .filter((s) => s.active && !s.archived)
    .map((s) => ({
      ...s,
      resourceIds: s.resourceIds.filter((id) => resources.some((r) => r.id === id)),
    }));
  return {
    mode: configuration.mode ?? "appointment",
    settings: configuration.settings,
    services,
    resources: resources.map(({ id, name }) => ({ id, name })),
  };
}

export function findService(
  configuration: ReservationConfiguration,
  id: string,
): ReservationService {
  const service = configuration.services.find((s) => s.id === id);
  if (!service) throw new ReservationError("NOT_FOUND");
  return service;
}

export function availableSlots(
  configuration: ReservationConfiguration,
  reservations: Reservation[],
  query: ReservationAvailabilityQuery,
  now: string,
  options: { staff?: boolean; reservation?: Reservation } = {},
): ReservationSlot[] {
  const { settings } = configuration;
  if (!options.staff && !options.reservation && !settings.publicBookingEnabled) return [];
  const service = findService(configuration, query.serviceId);
  if (!service.active || service.archived) return [];
  const policy = options.reservation?.policy ?? service;
  if ((policy.mode ?? "appointment") !== (configuration.mode ?? "appointment"))
    throw new ReservationError("MODE_MISMATCH");
  const zone = settings.timeZone;
  const date = Temporal.PlainDate.from(query.date);
  const earliest = options.staff ? now : addMinutes(now, policy.noticeMinutes);
  const lastDate = Temporal.PlainDate.from(localDate(now, zone))
    .add({ days: policy.horizonDays })
    .toString();
  if (query.date > lastDate || query.date < localDate(now, zone)) return [];
  if (policy.mode === "stay") {
    if (!query.departureDate || !dateSchema.safeParse(query.departureDate).success)
      throw new ReservationError("INVALID");
    const nights = stayNights(query.date, query.departureDate);
    if (nights < policy.minNights || nights > policy.maxNights)
      throw new ReservationError("INVALID");
  } else if (query.departureDate !== undefined) throw new ReservationError("INVALID");
  const resources = configuration.resources.filter(
    (r) =>
      r.active &&
      !r.archived &&
      service.resourceIds.includes(r.id) &&
      (!query.resourceId || query.resourceId === r.id),
  );
  const slots = new Map<string, ReservationSlot>();
  for (const resource of resources) {
    for (const h of policy.mode === "stay"
      ? [{ start: policy.arrivalStart, end: policy.arrivalEnd }]
      : hoursFor(resource, query.date)) {
      const [hour, minute] = h.start.split(":").map(Number);
      const [endHour, endMinute] = h.end.split(":").map(Number);
      for (
        let offset = hour * 60 + minute;
        offset < endHour * 60 + endMinute;
        offset += policy.intervalMinutes
      ) {
        const time = `${String(Math.floor(offset / 60)).padStart(2, "0")}:${String(offset % 60).padStart(2, "0")}`;
        for (const start of wallInstants(date.toString(), time, zone)) {
          const end = reservationEnd(policy, start, query.departureDate, zone);
          if (!end) continue;
          const occupiedStart = addMinutes(start, -policy.bufferBeforeMinutes);
          const occupiedEnd = addMinutes(end, policy.bufferAfterMinutes);
          if (
            start < earliest ||
            start <= now ||
            !fitsResource(resource, occupiedStart, occupiedEnd, zone, policy.mode)
          )
            continue;
          if (
            reservations.some(
              (r) =>
                r.id !== options.reservation?.id &&
                r.resourceId === resource.id &&
                activeReservation(r) &&
                overlaps(occupiedStart, occupiedEnd, r.occupiedStart, r.occupiedEnd),
            )
          )
            continue;
          slots.set(start, { startsAt: start, endsAt: end });
        }
      }
    }
  }
  return [...slots.values()].sort((a, b) => a.startsAt.localeCompare(b.startsAt));
}

export function placeReservation(
  configuration: ReservationConfiguration,
  reservations: Reservation[],
  input: ReservationBookingInput,
  now: string,
  id: string,
  options: { staff?: boolean; reservation?: Reservation } = {},
): Reservation {
  if (!options.staff && !options.reservation && !configuration.settings.publicBookingEnabled)
    throw new ReservationError("CLOSED");
  const service = findService(configuration, input.serviceId);
  const policy = options.reservation?.policy ?? parseReservationInput(policySchema, service);
  const zone = configuration.settings.timeZone;
  const date = localDate(input.startsAt, zone);
  const resource = [...configuration.resources]
    .sort((a, b) => a.id.localeCompare(b.id))
    .find(
      (r) =>
        (!input.resourceId || input.resourceId === r.id) &&
        availableSlots(
          configuration,
          reservations,
          { serviceId: service.id, resourceId: r.id, date, departureDate: input.departureDate },
          now,
          options,
        ).some((slot) => slot.startsAt === input.startsAt),
    );
  if (!resource) throw new ReservationError("CONFLICT");
  const end = reservationEnd(policy, input.startsAt, input.departureDate, zone);
  if (!end) throw new ReservationError("CONFLICT");
  return {
    mode: policy.mode ?? "appointment",
    ...(policy.mode === "stay"
      ? { departureDate: input.departureDate, nights: stayNights(date, input.departureDate!) }
      : {}),
    id,
    version: (options.reservation?.version ?? 0) + 1,
    serviceId: service.id,
    serviceName: options.reservation?.serviceName ?? service.name,
    resourceId: resource.id,
    resourceName: resource.name,
    status: policy.approval === "manual" ? "pending" : "confirmed",
    startsAt: input.startsAt,
    endsAt: end,
    occupiedStart: addMinutes(input.startsAt, -policy.bufferBeforeMinutes),
    occupiedEnd: addMinutes(end, policy.bufferAfterMinutes),
    cancellationDeadline: addMinutes(input.startsAt, -policy.cancellationMinutes),
    timeZone: zone,
    policy,
    customer: input.customer,
    locale: input.locale,
    createdAt: options.reservation?.createdAt ?? now,
    updatedAt: now,
  };
}

export function assertVersion(actual: number, expected: number) {
  if (!Number.isInteger(expected) || actual !== expected) throw new ReservationError("CONFLICT");
}

export function changeStatus(
  reservation: Reservation,
  status: Reservation["status"],
  now: string,
): Reservation {
  if (
    !activeReservation(reservation) ||
    status === "pending" ||
    (status === "confirmed" && (reservation.status !== "pending" || reservation.startsAt <= now)) ||
    (status === "rejected" && reservation.status !== "pending")
  )
    throw new ReservationError("CONFLICT");
  return { ...reservation, status, version: reservation.version + 1, updatedAt: now };
}

export function assertResourceExceptions(
  previous: ReservationResource | undefined,
  next: ReservationResource,
  reservations: Reservation[],
  timeZone: string,
) {
  for (const r of reservations.filter((r) => r.resourceId === next.id && activeReservation(r))) {
    if (r.mode === "stay") {
      if (
        JSON.stringify(next.blockedDates) !== JSON.stringify(previous?.blockedDates) &&
        !fitsResource(next, r.occupiedStart, r.occupiedEnd, timeZone, "stay")
      )
        throw new ReservationError("CONFLICT");
      continue;
    }
    const date = localDate(r.occupiedStart, timeZone);
    if (
      next.exceptions[date] !== undefined &&
      JSON.stringify(next.exceptions[date]) !== JSON.stringify(previous?.exceptions[date]) &&
      !fitsHours(next, r.occupiedStart, r.occupiedEnd, timeZone)
    )
      throw new ReservationError("CONFLICT");
  }
}

"use client";

import { RefreshCwIcon } from "lucide-react";
import { useCallback, useRef, useState } from "react";
import { Temporal } from "temporal-polyfill";

import {
  getReservationLabels,
  type ReservationLabels,
} from "@/components/plugins/reservations/labels";
import { addMinutes, localDate, stayNights } from "@/components/plugins/reservations/model";
import type {
  Reservation,
  ReservationCatalog,
  ReservationManagementClient,
  ReservationsPublicClient,
  ReservationSlot,
} from "@/components/plugins/reservations/types";
import {
  buttonClass,
  primaryClass,
  fieldClass,
  pageClass,
  panelClass,
  Field,
  DatePicker,
  StayDatePicker,
  ErrorNotice,
  formatDateTime,
  Modal,
  ReservationSummary,
  SlotPicker,
  useReservationAction,
  useReservationLoad,
} from "@/components/plugins/reservations/ui";
import { cn } from "@/components/utils/cn";

export interface ReservationBookingPageProps {
  client: ReservationsPublicClient;
  locale?: string;
  labels?: Partial<ReservationLabels>;
  initialDate?: string;
  onBooked?: (reservation: Reservation) => void;
  className?: string;
}

export function ReservationBookingPage({
  client,
  locale = "en",
  labels: overrides,
  initialDate,
  onBooked,
  className,
}: ReservationBookingPageProps) {
  const load = useCallback(() => client.catalog(), [client]);
  const data = useReservationLoad(load);
  const labels = getReservationLabels(overrides, data.value?.mode);
  const [receipt, setReceipt] = useState<Reservation>();
  return (
    <section className={cn(pageClass, className)}>
      <h1 className="font-serif text-3xl font-semibold">{labels.booking}</h1>
      <ErrorNotice error={data.error} labels={labels} />
      {data.error ? (
        <button className={buttonClass} onClick={data.reload}>
          <RefreshCwIcon className="size-4 shrink-0" aria-hidden="true" />
          {labels.refresh}
        </button>
      ) : !data.value ? (
        <output className="block">{labels.loading}</output>
      ) : receipt ? (
        <div className={cn(panelClass, "space-y-5")}>
          <output className="block">{labels.booked}</output>
          <ReservationSummary reservation={receipt} locale={locale} labels={labels} />
          <button className={buttonClass} onClick={() => setReceipt(undefined)}>
            {labels.another}
          </button>
        </div>
      ) : !data.value.settings.publicBookingEnabled ? (
        <output className="block">{labels.unavailable}</output>
      ) : !data.value.services.length ? (
        <output className="block">{labels.emptyServices}</output>
      ) : (
        <BookingForm
          client={client}
          catalog={data.value}
          labels={labels}
          locale={locale}
          initialDate={initialDate}
          onBooked={(value) => {
            setReceipt(value);
            onBooked?.(value);
          }}
        />
      )}
    </section>
  );
}

/** Also used by the staff's short create dialog. The host binds an authorized client. */
export function BookingForm({
  client,
  catalog,
  labels,
  locale,
  initialDate,
  onBooked,
  staff = false,
}: {
  client: ReservationsPublicClient;
  catalog: ReservationCatalog;
  labels: ReservationLabels;
  locale: string;
  initialDate?: string;
  onBooked: (reservation: Reservation) => void;
  staff?: boolean;
}) {
  const [serviceId, setServiceId] = useState(catalog.services[0]?.id ?? "");
  const [resourceId, setResourceId] = useState("");
  const [date, setDate] = useState(
    () => initialDate ?? localDate(new Date().toISOString(), catalog.settings.timeZone),
  );
  const [departureDate, setDepartureDate] = useState(() =>
    Temporal.PlainDate.from(date)
      .add({ days: catalog.services[0]?.mode === "stay" ? catalog.services[0].minNights : 1 })
      .toString(),
  );
  const [startsAt, setStartsAt] = useState("");
  const [customer, setCustomer] = useState({ name: "", email: "", phone: "" });
  const [reviewing, setReviewing] = useState(false);
  const request = useRef<{ input: string; id: string } | null>(null);
  const action = useReservationAction();
  const service = catalog.services.find((s) => s.id === serviceId);
  const stay = catalog.mode === "stay";
  const loadSlots = useCallback(
    () =>
      client.availability({
        serviceId,
        resourceId: resourceId || undefined,
        date,
        ...(stay ? { departureDate } : {}),
      }),
    [client, serviceId, resourceId, date, stay, departureDate],
  );
  const slots = useReservationLoad(loadSlots);
  const selectedSlot = slots.value?.find((slot) => slot.startsAt === startsAt);
  const zone = catalog.settings.timeZone;
  const resource = catalog.resources.find((r) => r.id === resourceId);
  const selectDate = (value: string) => {
    setDate(value);
    setStartsAt("");
    setReviewing(false);
  };
  if (!service) return <output className="block">{labels.emptyServices}</output>;
  return (
    <form
      className="space-y-5"
      onSubmit={(event) => {
        event.preventDefault();
        if (!reviewing && !staff) {
          setReviewing(true);
          return;
        }
        void action.run(async () => {
          const value = {
            serviceId,
            resourceId: resourceId || undefined,
            startsAt,
            ...(stay ? { departureDate } : {}),
            customer,
            locale,
          };
          const fingerprint = JSON.stringify(value);
          if (request.current?.input !== fingerprint)
            request.current = { input: fingerprint, id: crypto.randomUUID() };
          try {
            onBooked(await client.book({ ...value, requestId: request.current.id }));
          } catch (error) {
            setReviewing(false);
            slots.reload();
            throw error;
          }
        });
      }}
    >
      <ErrorNotice error={action.error} labels={labels} />
      {!reviewing ? (
        <>
          <div className="grid gap-4 sm:grid-cols-2">
            <Field label={labels.service}>
              <select
                className={fieldClass}
                value={serviceId}
                disabled={action.busy}
                onChange={(e) => {
                  setServiceId(e.target.value);
                  setResourceId("");
                  setStartsAt("");
                }}
              >
                {catalog.services.map((s) => (
                  <option key={s.id} value={s.id}>
                    {s.name}
                  </option>
                ))}
              </select>
            </Field>
            <Field label={labels.resource}>
              <select
                className={fieldClass}
                value={resourceId}
                disabled={action.busy}
                onChange={(e) => {
                  setResourceId(e.target.value);
                  setStartsAt("");
                }}
              >
                <option value="">{labels.anyResource}</option>
                {catalog.resources
                  .filter((r) => service.resourceIds.includes(r.id))
                  .map((r) => (
                    <option key={r.id} value={r.id}>
                      {r.name}
                    </option>
                  ))}
              </select>
            </Field>
          </div>
          {service.description && (
            <p className="text-sm text-muted-foreground">{service.description}</p>
          )}
          <p className="text-sm text-muted-foreground">
            {labels.timeZone}: {zone} ·{" "}
            {service.mode === "stay"
              ? `${labels.nights}: ${service.minNights}–${service.maxNights} · ${labels.checkoutTime}: ${service.checkoutTime}`
              : `${labels.duration}: ${service.durationMinutes}`}
          </p>
          <div className={cn(!staff && "grid gap-6 md:grid-cols-2")}>
            {service.mode === "stay" ? (
              <StayDatePicker
                arrival={date}
                departure={departureDate}
                minNights={service.minNights}
                labels={labels}
                locale={locale}
                onChange={(arrival, departure) => {
                  selectDate(arrival);
                  setDepartureDate(departure);
                }}
              />
            ) : staff ? (
              <Field label={labels.date}>
                <input
                  type="date"
                  required
                  className={fieldClass}
                  value={date}
                  onChange={(e) => {
                    if (e.target.value) selectDate(e.target.value);
                  }}
                />
              </Field>
            ) : (
              <div className={panelClass}>
                <DatePicker date={date} onChange={selectDate} labels={labels} locale={locale} />
              </div>
            )}
            <div className={cn(!staff && panelClass, "space-y-4")}>
              <ErrorNotice error={slots.error} labels={labels} />
              {slots.error ? (
                <button type="button" className={buttonClass} onClick={slots.reload}>
                  <RefreshCwIcon className="size-4 shrink-0" aria-hidden="true" />
                  {labels.refresh}
                </button>
              ) : !slots.value ? (
                <output className="block">{labels.loading}</output>
              ) : (
                <SlotPicker
                  slots={slots.value}
                  selected={startsAt}
                  onChange={setStartsAt}
                  labels={labels}
                  locale={locale}
                  zone={zone}
                />
              )}
            </div>
          </div>
          <div className="grid gap-4 sm:grid-cols-3">
            {(["name", "email", "phone"] as const).map((field) => (
              <Field key={field} label={labels[field]}>
                <input
                  className={fieldClass}
                  type={field === "email" ? "email" : field === "phone" ? "tel" : "text"}
                  required={field !== "phone"}
                  maxLength={field === "email" ? 254 : field === "name" ? 120 : 40}
                  autoComplete={field === "phone" ? "tel" : field}
                  value={customer[field]}
                  disabled={action.busy}
                  onChange={(e) => setCustomer({ ...customer, [field]: e.target.value })}
                />
              </Field>
            ))}
          </div>
        </>
      ) : (
        <div className={cn(panelClass, "space-y-3")}>
          <h2 className="text-xl font-semibold">{service.name}</h2>
          <p>{resource?.name ?? labels.anyResource}</p>
          <p>
            {stay && `${labels.arrivalDate}: `}
            {formatDateTime(startsAt, locale, zone)} · {zone}
          </p>
          <p>
            {service.mode === "stay" ? (
              <>
                {labels.departureDate}:{" "}
                {selectedSlot && formatDateTime(selectedSlot.endsAt, locale, zone)} ·{" "}
                {labels.nights}: {stayNights(date, departureDate)}
              </>
            ) : (
              <>
                {labels.duration}: {service.durationMinutes}
              </>
            )}
          </p>
          <p>
            {customer.name} · {customer.email}
          </p>
        </div>
      )}
      {startsAt && (
        <p className="text-sm">
          {labels.cancellationDeadline}:{" "}
          {formatDateTime(addMinutes(startsAt, -service.cancellationMinutes), locale, zone)}
        </p>
      )}
      <p className="text-sm text-muted-foreground">
        {service.approval === "manual" ? labels.approvalRequired : labels.automaticApproval}
      </p>
      <div className="flex flex-wrap gap-3">
        {reviewing && (
          <button
            type="button"
            className={buttonClass}
            disabled={action.busy}
            onClick={() => setReviewing(false)}
          >
            {labels.back}
          </button>
        )}
        <button
          type="submit"
          className={primaryClass}
          disabled={
            !startsAt ||
            action.busy ||
            (!reviewing && !slots.value?.some((s) => s.startsAt === startsAt))
          }
        >
          {action.busy ? labels.saving : reviewing || staff ? labels.book : labels.review}
        </button>
      </div>
    </form>
  );
}

export interface ReservationManagePageProps {
  client: ReservationManagementClient;
  locale?: string;
  labels?: Partial<ReservationLabels>;
  className?: string;
}

export function ReservationManagePage({
  client,
  locale = "en",
  labels: overrides,
  className,
}: ReservationManagePageProps) {
  const load = useCallback(() => client.get(), [client]);
  const data = useReservationLoad(load);
  const labels = getReservationLabels(overrides, data.value?.reservation.mode);
  const [dialog, setDialog] = useState<"cancel" | "move">();
  const action = useReservationAction();
  const r = data.value?.reservation;
  const availability = useCallback(
    (query: { date: string; resourceId?: string; departureDate?: string }) =>
      client.availability(query),
    [client],
  );
  const reschedule = useCallback(
    (input: Parameters<ReservationManagementClient["reschedule"]>[0]) => client.reschedule(input),
    [client],
  );
  return (
    <section className={cn(pageClass, "max-w-3xl", className)}>
      <h1 className="font-serif text-3xl font-semibold">{labels.manage}</h1>
      <ErrorNotice error={data.error ?? action.error} labels={labels} />
      {data.error ? (
        <button className={buttonClass} onClick={data.reload}>
          <RefreshCwIcon className="size-4 shrink-0" aria-hidden="true" />
          {labels.refresh}
        </button>
      ) : !r ? (
        <output className="block">{labels.loading}</output>
      ) : (
        <div className={cn(panelClass, "space-y-5")}>
          <ReservationSummary reservation={r} locale={locale} labels={labels} />
          {data.value?.canChange ? (
            <div className="flex flex-wrap gap-3">
              <button className={buttonClass} onClick={() => setDialog("move")}>
                {labels.reschedule}
              </button>
              <button className={buttonClass} onClick={() => setDialog("cancel")}>
                {labels.cancel}
              </button>
            </div>
          ) : (
            (r.status === "pending" || r.status === "confirmed") && (
              <p className="text-sm text-muted-foreground">{labels.cutoff}</p>
            )
          )}
          {dialog === "cancel" && (
            <Modal
              title={labels.cancel}
              description={labels.cancelConfirm}
              onClose={() => setDialog(undefined)}
              busy={action.busy}
            >
              <ErrorNotice error={action.error} labels={labels} />
              <div className="flex flex-wrap gap-3">
                <button
                  className={buttonClass}
                  disabled={action.busy}
                  onClick={() => setDialog(undefined)}
                >
                  {labels.keep}
                </button>
                <button
                  className={primaryClass}
                  disabled={action.busy}
                  onClick={() => {
                    void action.run(async () => {
                      await client.cancel(r.version);
                      setDialog(undefined);
                      data.reload();
                    });
                  }}
                >
                  {labels.cancel}
                </button>
              </div>
            </Modal>
          )}
          {dialog === "move" && (
            <RescheduleDialog
              reservation={r}
              timeZone={data.value?.timeZone ?? r.timeZone}
              resources={data.value?.resources ?? []}
              labels={labels}
              locale={locale}
              availability={availability}
              onSave={reschedule}
              onClose={() => setDialog(undefined)}
              onSaved={() => {
                setDialog(undefined);
                data.reload();
              }}
            />
          )}
        </div>
      )}
    </section>
  );
}

export function RescheduleDialog({
  reservation,
  timeZone,
  resources,
  labels,
  locale,
  availability,
  onSave,
  onSaved,
  onClose,
}: {
  reservation: Reservation;
  timeZone: string;
  resources: { id: string; name: string }[];
  labels: ReservationLabels;
  locale: string;
  availability: (query: {
    date: string;
    resourceId?: string;
    departureDate?: string;
  }) => Promise<ReservationSlot[]>;
  onSave: ReservationManagementClient["reschedule"];
  onSaved: () => void;
  onClose: () => void;
}) {
  const [date, setDate] = useState(() => localDate(reservation.startsAt, timeZone));
  const stay = reservation.policy.mode === "stay";
  const [departureDate, setDepartureDate] = useState(() => localDate(reservation.endsAt, timeZone));
  const [resourceId, setResourceId] = useState(
    resources.some((r) => r.id === reservation.resourceId) ? reservation.resourceId : "",
  );
  const [startsAt, setStartsAt] = useState("");
  const load = useCallback(
    () =>
      availability({
        date,
        resourceId: resourceId || undefined,
        ...(stay ? { departureDate } : {}),
      }),
    [availability, date, resourceId, stay, departureDate],
  );
  const slots = useReservationLoad(load);
  const action = useReservationAction();
  return (
    <Modal
      title={labels.reschedule}
      description={
        reservation.policy.approval === "manual" ? labels.moveWarning : labels.automaticApproval
      }
      onClose={onClose}
      busy={action.busy}
    >
      <form
        className="space-y-4"
        onSubmit={(e) => {
          e.preventDefault();
          void action.run(async () => {
            try {
              await onSave({
                version: reservation.version,
                startsAt,
                ...(stay ? { departureDate } : {}),
                resourceId: resourceId || undefined,
              });
              onSaved();
            } catch (error) {
              slots.reload();
              throw error;
            }
          });
        }}
      >
        <ErrorNotice error={action.error ?? slots.error} labels={labels} />
        <Field label={labels.resource}>
          <select
            value={resourceId}
            className={fieldClass}
            onChange={(e) => {
              setResourceId(e.target.value);
              setStartsAt("");
            }}
          >
            <option value="">{labels.anyResource}</option>
            {resources.map((r) => (
              <option key={r.id} value={r.id}>
                {r.name}
              </option>
            ))}
          </select>
        </Field>
        {reservation.policy.mode === "stay" ? (
          <StayDatePicker
            arrival={date}
            departure={departureDate}
            minNights={reservation.policy.minNights}
            labels={labels}
            locale={locale}
            onChange={(arrival, departure) => {
              setDate(arrival);
              setDepartureDate(departure);
              setStartsAt("");
            }}
          />
        ) : (
          <Field label={labels.date}>
            <input
              className={fieldClass}
              required
              type="date"
              value={date}
              onChange={(e) => {
                if (e.target.value) {
                  setDate(e.target.value);
                  setStartsAt("");
                }
              }}
            />
          </Field>
        )}
        <p className="text-sm text-muted-foreground">
          {timeZone}
          {reservation.policy.mode === "stay" &&
            ` · ${labels.checkoutTime}: ${reservation.policy.checkoutTime} · ${labels.nights}: ${stayNights(date, departureDate)}`}
        </p>
        {slots.value ? (
          <SlotPicker
            slots={slots.value}
            selected={startsAt}
            onChange={setStartsAt}
            locale={locale}
            labels={labels}
            zone={timeZone}
          />
        ) : (
          !slots.error && <output className="block">{labels.loading}</output>
        )}
        {!!slots.error && (
          <button type="button" className={buttonClass} onClick={slots.reload}>
            <RefreshCwIcon className="size-4 shrink-0" aria-hidden="true" />
            {labels.refresh}
          </button>
        )}
        <div className="flex flex-wrap gap-3">
          <button type="button" className={buttonClass} disabled={action.busy} onClick={onClose}>
            {labels.close}
          </button>
          <button
            className={primaryClass}
            disabled={
              !startsAt || action.busy || !slots.value?.some((s) => s.startsAt === startsAt)
            }
          >
            {labels.saveMove}
          </button>
        </div>
      </form>
    </Modal>
  );
}

"use client";

import { PencilIcon, PlusIcon, RefreshCwIcon, Trash2Icon } from "lucide-react";
import { useCallback, useState } from "react";
import type { ComponentType } from "react";

import { Link, type LinkProps } from "@/components/link";
import {
  getReservationLabels,
  type ReservationLabels,
} from "@/components/plugins/reservations/labels";
import {
  reservationPolicyDefaults,
  reservationStayPolicyDefaults,
} from "@/components/plugins/reservations/model";
import type {
  ReservationConfiguration,
  ReservationHours,
  ReservationMode,
  ReservationResource,
  ReservationService,
  ReservationSettings,
  ReservationsAdminClient,
} from "@/components/plugins/reservations/types";
import {
  buttonClass,
  primaryClass,
  fieldClass,
  pageClass,
  panelClass,
  Field,
  ErrorNotice,
  Modal,
  useReservationAction,
  useReservationLoad,
} from "@/components/plugins/reservations/ui";
import { cn } from "@/components/utils/cn";

export interface ReservationSettingsPageProps {
  client: ReservationsAdminClient;
  editor?: { kind: "service" | "resource"; id: string };
  getServiceHref: (id: string) => string;
  getResourceHref: (id: string) => string;
  backHref: string;
  onSaved?: (kind: "service" | "resource", id: string) => void;
  labels?: Partial<ReservationLabels>;
  className?: string;
  linkComponent?: ComponentType<LinkProps>;
}

export function ReservationSettingsPage({
  client,
  editor,
  getServiceHref,
  getResourceHref,
  backHref,
  onSaved,
  labels: overrides,
  className,
  linkComponent: HostLink = Link,
}: ReservationSettingsPageProps) {
  const load = useCallback(() => client.configuration(), [client]);
  const data = useReservationLoad(load);
  const config = data.value;
  const labels = getReservationLabels(overrides, config?.mode);
  const item =
    editor?.kind === "service"
      ? config?.services.find((s) => s.id === editor.id)
      : config?.resources.find((r) => r.id === editor?.id);
  return (
    <section className={cn(pageClass, className)}>
      <HostLink className={buttonClass} href={backHref}>
        {labels.back}
      </HostLink>
      <h1 className="font-serif text-3xl font-semibold">
        {editor ? (editor.kind === "service" ? labels.service : labels.resource) : labels.settings}
      </h1>
      <ErrorNotice error={data.error} labels={labels} />
      {data.error ? (
        <button className={buttonClass} onClick={data.reload}>
          <RefreshCwIcon className="size-4 shrink-0" aria-hidden="true" />
          {labels.refresh}
        </button>
      ) : !config ? (
        <output className="block">{labels.loading}</output>
      ) : editor ? (
        editor.id !== "new" && !item ? (
          <p role="alert">{labels.invalid}</p>
        ) : editor.kind === "service" ? (
          <ServiceEditor
            key={editor.id}
            value={item as ReservationService | undefined}
            config={config}
            client={client}
            labels={labels}
            onSaved={(id) => onSaved?.("service", id)}
          />
        ) : (
          <ResourceEditor
            key={editor.id}
            mode={config.mode}
            value={item as ReservationResource | undefined}
            client={client}
            labels={labels}
            onSaved={(id) => onSaved?.("resource", id)}
          />
        )
      ) : (
        <>
          <BusinessSettings value={config.settings} client={client} labels={labels} />
          {(["service", "resource"] as const).map((kind) => (
            <div key={kind} className={cn(panelClass, "space-y-4")}>
              <div className="flex flex-wrap items-center justify-between gap-3">
                <h2 className="text-xl font-semibold">
                  {kind === "service" ? labels.services : labels.resources}
                </h2>
                <HostLink
                  className={buttonClass}
                  href={kind === "service" ? getServiceHref("new") : getResourceHref("new")}
                >
                  <PlusIcon className="size-4 shrink-0" aria-hidden="true" />
                  {kind === "service" ? labels.newService : labels.newResource}
                </HostLink>
              </div>
              <ul className="divide-y divide-border">
                {(kind === "service" ? config.services : config.resources).map((entry) => (
                  <li key={entry.id} className="flex items-center justify-between gap-3 py-3">
                    <div>
                      <span className="font-medium">{entry.name}</span>
                      {entry.archived && (
                        <span className="ml-2 text-sm text-muted-foreground">
                          {labels.archived}
                        </span>
                      )}
                    </div>
                    <HostLink
                      className={cn(buttonClass, "size-10 p-0")}
                      href={
                        kind === "service" ? getServiceHref(entry.id) : getResourceHref(entry.id)
                      }
                      aria-label={`${labels.edit} ${entry.name}`}
                    >
                      <PencilIcon aria-hidden="true" className="size-4 shrink-0" />
                    </HostLink>
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </>
      )}
    </section>
  );
}

function BusinessSettings({
  value,
  client,
  labels,
}: {
  value: ReservationSettings;
  client: ReservationsAdminClient;
  labels: ReservationLabels;
}) {
  const [draft, setDraft] = useState(value);
  const [saved, setSaved] = useState(false);
  const action = useReservationAction();
  return (
    <form
      className={cn(panelClass, "space-y-4")}
      onSubmit={(e) => {
        e.preventDefault();
        setSaved(false);
        void action.run(async () => {
          setDraft(await client.saveSettings(draft));
          setSaved(true);
        });
      }}
    >
      <h2 className="text-xl font-semibold">{labels.business}</h2>
      <ErrorNotice error={action.error} labels={labels} />
      <Field label={labels.timeZone}>
        <input
          className={fieldClass}
          required
          value={draft.timeZone}
          placeholder="Europe/Zurich"
          onChange={(e) => {
            setDraft({ ...draft, timeZone: e.target.value });
            setSaved(false);
          }}
        />
      </Field>
      <label className="flex items-center gap-2 text-sm">
        <input
          type="checkbox"
          checked={draft.publicBookingEnabled}
          onChange={(e) => {
            setDraft({ ...draft, publicBookingEnabled: e.target.checked });
            setSaved(false);
          }}
        />
        {labels.publicEnabled}
      </label>
      <button className={primaryClass} disabled={action.busy}>
        {action.busy ? labels.saving : labels.save}
      </button>
      {saved && <output className="block">{labels.saved}</output>}
    </form>
  );
}

const policyFields = [
  ["durationMinutes", "duration", 1, 1440],
  ["bufferBeforeMinutes", "bufferBefore", 0, 1440],
  ["bufferAfterMinutes", "bufferAfter", 0, 1440],
  ["cancellationMinutes", "cancellation", 0, 525600],
  ["noticeMinutes", "notice", 0, 525600],
  ["horizonDays", "horizon", 1, 365],
  ["intervalMinutes", "interval", 1, 1440],
] as const;

function ServiceEditor({
  value,
  config,
  client,
  labels,
  onSaved,
}: {
  value?: ReservationService;
  config: ReservationConfiguration;
  client: ReservationsAdminClient;
  labels: ReservationLabels;
  onSaved: (id: string) => void;
}) {
  const [draft, setDraft] = useState<ReservationService>(
    () =>
      value ?? {
        ...reservationPolicyDefaults,
        id: "",
        version: 0,
        name: "",
        description: "",
        ...(config.mode === "stay"
          ? { ...reservationStayPolicyDefaults, arrivalStart: "", arrivalEnd: "", checkoutTime: "" }
          : { durationMinutes: 0 }),
        active: false,
        archived: false,
        resourceIds: [],
      },
  );
  const [saved, setSaved] = useState(false);
  const [archiving, setArchiving] = useState(false);
  const action = useReservationAction();
  const save = async (archive = false) => {
    const input = {
      ...draft,
      id: draft.id || crypto.randomUUID(),
      archived: archive || draft.archived,
    };
    setDraft(input);
    setSaved(false);
    const next = await client.saveService(input);
    setDraft(next);
    setSaved(true);
    setArchiving(false);
    onSaved(next.id);
  };
  return (
    <form
      className="space-y-6"
      onSubmit={(e) => {
        e.preventDefault();
        void action.run(() => save());
      }}
    >
      <ErrorNotice error={action.error} labels={labels} />
      <div className={cn(panelClass, "space-y-4")}>
        <Field label={labels.name}>
          <input
            className={fieldClass}
            required
            maxLength={120}
            value={draft.name}
            onChange={(e) => {
              setDraft({ ...draft, name: e.target.value });
              setSaved(false);
            }}
          />
        </Field>
        <Field label={labels.description}>
          <textarea
            className={fieldClass}
            maxLength={2000}
            value={draft.description}
            onChange={(e) => {
              setDraft({ ...draft, description: e.target.value });
              setSaved(false);
            }}
          />
        </Field>
        <label className="flex items-center gap-2 text-sm">
          <input
            type="checkbox"
            checked={draft.active}
            disabled={draft.archived}
            onChange={(e) => {
              setDraft({ ...draft, active: e.target.checked });
              setSaved(false);
            }}
          />
          {labels.active}
        </label>
      </div>
      <fieldset className={cn(panelClass, "space-y-3")}>
        <legend className="px-2 font-medium">{labels.eligibleResources}</legend>
        {config.resources
          .filter((r) => !r.archived)
          .map((r) => (
            <label key={r.id} className="flex items-center gap-2 text-sm">
              <input
                type="checkbox"
                checked={draft.resourceIds.includes(r.id)}
                onChange={(e) => {
                  setDraft({
                    ...draft,
                    resourceIds: e.target.checked
                      ? [...draft.resourceIds, r.id]
                      : draft.resourceIds.filter((id) => id !== r.id),
                  });
                  setSaved(false);
                }}
              />
              {r.name}
            </label>
          ))}
      </fieldset>
      <div className={cn(panelClass, "space-y-5")}>
        <p className="text-sm text-muted-foreground">{labels.policyHelp}</p>
        <div className="grid gap-4 sm:grid-cols-2">
          {policyFields
            .filter(([field]) => field !== "durationMinutes" || draft.mode !== "stay")
            .map(([field, label, min, max]) => (
              <Field key={field} label={labels[label]}>
                <input
                  className={fieldClass}
                  type="number"
                  required
                  min={min}
                  max={max}
                  step={1}
                  value={draft[field] || (field === "durationMinutes" ? "" : 0)}
                  onChange={(e) => {
                    setDraft({ ...draft, [field]: e.target.valueAsNumber });
                    setSaved(false);
                  }}
                />
              </Field>
            ))}
          {draft.mode === "stay" && (
            <>
              {(["arrivalStart", "arrivalEnd", "checkoutTime"] as const).map((field) => (
                <Field key={field} label={labels[field]}>
                  <input
                    type="time"
                    required
                    className={fieldClass}
                    value={draft[field]}
                    onChange={(e) => {
                      setDraft({ ...draft, [field]: e.target.value });
                      setSaved(false);
                    }}
                  />
                </Field>
              ))}
              {(["minNights", "maxNights"] as const).map((field) => (
                <Field key={field} label={labels[field]}>
                  <input
                    type="number"
                    required
                    min={1}
                    max={365}
                    step={1}
                    className={fieldClass}
                    value={draft[field]}
                    onChange={(e) => {
                      setDraft({ ...draft, [field]: e.target.valueAsNumber });
                      setSaved(false);
                    }}
                  />
                </Field>
              ))}
            </>
          )}
          <Field label={labels.approval}>
            <select
              className={fieldClass}
              value={draft.approval}
              onChange={(e) => {
                setDraft({ ...draft, approval: e.target.value as "automatic" | "manual" });
                setSaved(false);
              }}
            >
              <option value="automatic">{labels.automatic}</option>
              <option value="manual">{labels.manual}</option>
            </select>
          </Field>
        </div>
      </div>
      <div className="flex items-center gap-3">
        <button className={primaryClass} disabled={action.busy}>
          {action.busy ? labels.saving : labels.save}
        </button>
        {draft.version > 0 && !draft.archived && (
          <ArchiveButton labels={labels} onClick={() => setArchiving(true)} />
        )}
        {draft.archived && <span>{labels.archived}</span>}
        {saved && <output className="block">{labels.saved}</output>}
      </div>
      {archiving && (
        <ArchiveDialog
          labels={labels}
          action={action}
          onClose={() => setArchiving(false)}
          onArchive={() => save(true)}
        />
      )}
    </form>
  );
}

function HoursEditor({
  value,
  onChange,
  labels,
}: {
  value: ReservationHours[];
  onChange: (value: ReservationHours[]) => void;
  labels: ReservationLabels;
}) {
  return (
    <div className="space-y-3">
      {!value.length && <p className="text-sm text-muted-foreground">{labels.closed}</p>}
      {value.map((hours, i) => (
        <div key={i} className="flex flex-wrap items-end gap-2">
          <Field label={labels.start}>
            <input
              className={fieldClass}
              type="time"
              required
              value={hours.start}
              onChange={(e) =>
                onChange(value.map((h, j) => (j === i ? { ...h, start: e.target.value } : h)))
              }
            />
          </Field>
          <Field label={labels.end}>
            <input
              className={cn(fieldClass, "max-w-36")}
              type="text"
              inputMode="numeric"
              required
              pattern="([01][0-9]|2[0-3]):[0-5][0-9]|24:00"
              value={hours.end}
              onChange={(e) =>
                onChange(value.map((h, j) => (j === i ? { ...h, end: e.target.value } : h)))
              }
            />
          </Field>
          <button
            type="button"
            className={cn(buttonClass, "size-10 p-0")}
            aria-label={`${labels.remove} ${hours.start}–${hours.end}`}
            onClick={() => onChange(value.filter((_, j) => j !== i))}
          >
            <Trash2Icon className="size-4 shrink-0" aria-hidden="true" />
          </button>
        </div>
      ))}
      <button
        type="button"
        className={buttonClass}
        onClick={() => onChange([...value, { start: "09:00", end: "17:00" }])}
      >
        <PlusIcon className="size-4 shrink-0" aria-hidden="true" />
        {labels.addHours}
      </button>
    </div>
  );
}

function ResourceEditor({
  mode,
  value,
  client,
  labels,
  onSaved,
}: {
  mode: ReservationMode;
  value?: ReservationResource;
  client: ReservationsAdminClient;
  labels: ReservationLabels;
  onSaved: (id: string) => void;
}) {
  const [draft, setDraft] = useState<ReservationResource>(
    () =>
      value ?? {
        id: "",
        version: 0,
        name: "",
        active: false,
        archived: false,
        weeklyHours: {},
        exceptions: {},
        ...(mode === "stay" ? { blockedDates: [] } : {}),
      },
  );
  const [date, setDate] = useState("");
  const [saved, setSaved] = useState(false);
  const [archiving, setArchiving] = useState(false);
  const action = useReservationAction();
  const change = (value: ReservationResource) => {
    setDraft(value);
    setSaved(false);
  };
  const save = async (archive = false) => {
    const input = {
      ...draft,
      id: draft.id || crypto.randomUUID(),
      archived: archive || draft.archived,
    };
    change(input);
    const next = await client.saveResource(input);
    setDraft(next);
    setSaved(true);
    setArchiving(false);
    onSaved(next.id);
  };
  return (
    <form
      className="space-y-6"
      onSubmit={(e) => {
        e.preventDefault();
        void action.run(() => save());
      }}
    >
      <ErrorNotice error={action.error} labels={labels} />
      <div className={cn(panelClass, "space-y-4")}>
        <Field label={labels.name}>
          <input
            className={fieldClass}
            required
            maxLength={120}
            value={draft.name}
            onChange={(e) => change({ ...draft, name: e.target.value })}
          />
        </Field>
        <label className="flex items-center gap-2 text-sm">
          <input
            type="checkbox"
            checked={draft.active}
            disabled={draft.archived}
            onChange={(e) => change({ ...draft, active: e.target.checked })}
          />
          {labels.active}
        </label>
      </div>
      {mode === "stay" ? (
        <div className={cn(panelClass, "space-y-4")}>
          <h2 className="text-xl font-semibold">{labels.blockedDates}</h2>
          <p className="text-sm text-muted-foreground">{labels.closuresHelp}</p>
          {(draft.blockedDates ?? []).map((block, index) => (
            <div key={index} className="flex flex-wrap items-end gap-2">
              {(["from", "through"] as const).map((field) => (
                <Field
                  key={field}
                  label={field === "from" ? labels.blockedFrom : labels.blockedThrough}
                >
                  <input
                    type="date"
                    required
                    className={fieldClass}
                    value={block[field]}
                    min={field === "through" ? block.from : undefined}
                    onChange={(e) =>
                      change({
                        ...draft,
                        blockedDates: draft.blockedDates!.map((old, i) =>
                          i === index ? { ...old, [field]: e.target.value } : old,
                        ),
                      })
                    }
                  />
                </Field>
              ))}
              <button
                type="button"
                className={cn(buttonClass, "size-10 p-0")}
                aria-label={`${labels.remove} ${block.from}–${block.through}`}
                onClick={() =>
                  change({
                    ...draft,
                    blockedDates: draft.blockedDates!.filter((_, i) => i !== index),
                  })
                }
              >
                <Trash2Icon aria-hidden="true" className="size-4 shrink-0" />
              </button>
            </div>
          ))}
          <button
            type="button"
            className={buttonClass}
            onClick={() =>
              change({
                ...draft,
                blockedDates: [...(draft.blockedDates ?? []), { from: "", through: "" }],
              })
            }
          >
            <PlusIcon aria-hidden="true" className="size-4 shrink-0" />
            {labels.addClosure}
          </button>
        </div>
      ) : (
        <>
          <h2 className="text-xl font-semibold">{labels.hours}</h2>
          <p className="text-sm text-muted-foreground">{labels.hoursHelp}</p>
          <div className="grid gap-4 sm:grid-cols-2">
            {Array.from({ length: 7 }, (_, i) => String(i + 1)).map((day) => (
              <fieldset className={panelClass} key={day}>
                <legend className="px-2 font-medium">
                  {labels[`weekday${day}` as keyof ReservationLabels]}
                </legend>
                <HoursEditor
                  value={draft.weeklyHours[day] ?? []}
                  onChange={(hours) =>
                    change({ ...draft, weeklyHours: { ...draft.weeklyHours, [day]: hours } })
                  }
                  labels={labels}
                />
              </fieldset>
            ))}
          </div>
          <div className={cn(panelClass, "space-y-4")}>
            <h2 className="text-xl font-semibold">{labels.exceptions}</h2>
            <div className="flex flex-wrap items-end gap-3">
              <Field label={labels.date}>
                <input
                  type="date"
                  className={fieldClass}
                  value={date}
                  onChange={(e) => setDate(e.target.value)}
                />
              </Field>
              <button
                type="button"
                disabled={!date || date in draft.exceptions}
                className={buttonClass}
                onClick={() => {
                  change({ ...draft, exceptions: { ...draft.exceptions, [date]: [] } });
                  setDate("");
                }}
              >
                <PlusIcon className="size-4 shrink-0" aria-hidden="true" />
                {labels.addException}
              </button>
            </div>
            {Object.entries(draft.exceptions)
              .sort(([a], [b]) => a.localeCompare(b))
              .map(([day, hours]) => (
                <fieldset key={day} className="space-y-3 rounded-xl border border-border p-4">
                  <legend className="px-2 font-medium">{day}</legend>
                  <HoursEditor
                    value={hours}
                    labels={labels}
                    onChange={(next) =>
                      change({ ...draft, exceptions: { ...draft.exceptions, [day]: next } })
                    }
                  />
                  <button
                    type="button"
                    className={cn(buttonClass, "size-10 p-0")}
                    aria-label={`${labels.remove} ${day}`}
                    onClick={() => {
                      const exceptions = { ...draft.exceptions };
                      delete exceptions[day];
                      change({ ...draft, exceptions });
                    }}
                  >
                    <Trash2Icon className="size-4 shrink-0" aria-hidden="true" />
                  </button>
                </fieldset>
              ))}
          </div>
        </>
      )}
      <div className="flex items-center gap-3">
        <button className={primaryClass} disabled={action.busy}>
          {action.busy ? labels.saving : labels.save}
        </button>
        {draft.version > 0 && !draft.archived && (
          <ArchiveButton labels={labels} onClick={() => setArchiving(true)} />
        )}
        {draft.archived && <span>{labels.archived}</span>}
        {saved && <output className="block">{labels.saved}</output>}
      </div>
      {archiving && (
        <ArchiveDialog
          labels={labels}
          action={action}
          onClose={() => setArchiving(false)}
          onArchive={() => save(true)}
        />
      )}
    </form>
  );
}

function ArchiveButton({ labels, onClick }: { labels: ReservationLabels; onClick: () => void }) {
  return (
    <button
      type="button"
      className={cn(buttonClass, "size-10 p-0 text-destructive")}
      aria-label={labels.archive}
      onClick={onClick}
    >
      <Trash2Icon className="size-4 shrink-0" aria-hidden="true" />
    </button>
  );
}
function ArchiveDialog({
  labels,
  action,
  onClose,
  onArchive,
}: {
  labels: ReservationLabels;
  action: ReturnType<typeof useReservationAction>;
  onClose: () => void;
  onArchive: () => Promise<void>;
}) {
  return (
    <Modal
      title={labels.archive}
      description={labels.archiveConfirm}
      onClose={onClose}
      busy={action.busy}
    >
      <ErrorNotice error={action.error} labels={labels} />
      <div className="flex gap-3">
        <button type="button" className={buttonClass} onClick={onClose} disabled={action.busy}>
          {labels.back}
        </button>
        <button
          type="button"
          className={primaryClass}
          disabled={action.busy}
          onClick={() => {
            void action.run(onArchive);
          }}
        >
          {labels.archive}
        </button>
      </div>
    </Modal>
  );
}

export type ReservationStatus = "pending" | "confirmed" | "rejected" | "cancelled";

export type ReservationMode = "appointment" | "stay";

export interface ReservationCommonPolicy {
  bufferBeforeMinutes: number;
  bufferAfterMinutes: number;
  cancellationMinutes: number;
  approval: "automatic" | "manual";
  noticeMinutes: number;
  horizonDays: number;
  intervalMinutes: number;
}

export interface ReservationAppointmentPolicy extends ReservationCommonPolicy {
  /** Missing mode on legacy documents means appointment. */
  mode?: "appointment";
  durationMinutes: number;
}

export interface ReservationStayPolicy extends ReservationCommonPolicy {
  mode: "stay";
  arrivalStart: string;
  arrivalEnd: string;
  checkoutTime: string;
  minNights: number;
  maxNights: number;
  durationMinutes?: never;
}

export type ReservationPolicy = ReservationAppointmentPolicy | ReservationStayPolicy;

export type ReservationService = ReservationPolicy & {
  id: string;
  version: number;
  name: string;
  description: string;
  resourceIds: string[];
  active: boolean;
  archived: boolean;
};

/** Local wall-clock intervals. An end of 24:00 means the end of that day. */
export interface ReservationHours {
  start: string;
  end: string;
}

export interface ReservationResource {
  id: string;
  version: number;
  name: string;
  active: boolean;
  archived: boolean;
  /** ISO weekdays 1 (Monday) through 7 (Sunday). Missing weekdays are closed. */
  weeklyHours: Record<string, ReservationHours[]>;
  /** Replaces the entire day's weekly hours; [] closes the date. */
  exceptions: Record<string, ReservationHours[]>;
  /** Inclusive local calendar dates; stay mode only. */
  blockedDates?: { from: string; through: string }[];
}

export interface ReservationSettings {
  version: number;
  timeZone: string;
  publicBookingEnabled: boolean;
}

export interface ReservationCustomer {
  name: string;
  email: string;
  phone: string;
}

export interface Reservation {
  mode: ReservationMode;
  departureDate?: string;
  nights?: number;
  id: string;
  version: number;
  serviceId: string;
  serviceName: string;
  resourceId: string;
  resourceName: string;
  status: ReservationStatus;
  startsAt: string;
  endsAt: string;
  occupiedStart: string;
  occupiedEnd: string;
  cancellationDeadline: string;
  timeZone: string;
  policy: ReservationPolicy;
  customer: ReservationCustomer;
  locale: string;
  createdAt: string;
  updatedAt: string;
}

export interface ReservationCatalog {
  mode: ReservationMode;
  settings: ReservationSettings;
  services: ReservationService[];
  resources: Pick<ReservationResource, "id" | "name">[];
}

export interface ReservationSlot {
  startsAt: string;
  endsAt: string;
}

export interface ReservationAvailabilityQuery {
  serviceId: string;
  resourceId?: string;
  date: string;
  departureDate?: string;
}

export interface ReservationBookingInput {
  /** Required in stay mode; rejected in appointment mode. */
  departureDate?: string;
  requestId: string;
  serviceId: string;
  resourceId?: string;
