export type ReservationErrorCode =
  | "MODE_MISMATCH"
  | "INVALID"
  | "NOT_FOUND"
  | "FORBIDDEN"
  | "CONFLICT"
  | "CUTOFF"
  | "CLOSED"
  | "INVALID_LINK"
  | "STORAGE";

export class ReservationError extends Error {
  readonly code: ReservationErrorCode;
  constructor(code: ReservationErrorCode) {
    super(code);
    this.name = "ReservationError";
    this.code = code;
  }
}

