export function DatePicker({
  date,
  onChange,
  locale,
  labels,
  minDate,
  range,
  showInput = true,
}: {
  date: string;
  onChange: (date: string) => void;
  locale: string;
  labels: ReservationLabels;
  minDate?: string;
  range?: { from: string; to: string };
  showInput?: boolean;
}) {
  const selected = Temporal.PlainDate.from(date);
  const [month, setMonth] = useState(() => selected.with({ day: 1 }).toString());
  const start = Temporal.PlainDate.from(month);
  const gridStart = start.subtract({ days: start.dayOfWeek - 1 });
  const monthLabel = new Intl.DateTimeFormat(locale, {
    month: "long",
    year: "numeric",
    timeZone: "UTC",
  }).format(new Date(`${month}T12:00:00Z`));
  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between gap-2">
        <button
          type="button"
          className={buttonClass}
          aria-label={labels.previous}
          onClick={() => setMonth(start.subtract({ months: 1 }).toString())}
        >
          <ChevronLeftIcon className="size-4" aria-hidden="true" />
        </button>
        <span className="font-medium" aria-live="polite">
          {monthLabel}
        </span>
        <button
          type="button"
          className={buttonClass}
          aria-label={labels.next}
          onClick={() => setMonth(start.add({ months: 1 }).toString())}
        >
          <ChevronRightIcon className="size-4" aria-hidden="true" />
        </button>
      </div>
      <div className="grid grid-cols-7 gap-1">
        {Array.from({ length: 7 }, (_, i) => (
          <span key={i} className="py-1 text-center text-xs text-muted-foreground">
            {new Intl.DateTimeFormat(locale, { weekday: "short", timeZone: "UTC" }).format(
              new Date(`2026-09-${String(21 + i)}T12:00:00Z`),
            )}
          </span>
        ))}
        {Array.from({ length: 42 }, (_, i) => {
          const day = gridStart.add({ days: i });
          const value = day.toString();
          return (
            <button
              type="button"
              key={value}
              disabled={!!minDate && value < minDate}
              aria-pressed={range ? value >= range.from && value <= range.to : date === value}
              aria-label={new Intl.DateTimeFormat(locale, {
                dateStyle: "full",
                timeZone: "UTC",
              }).format(new Date(`${value}T12:00:00Z`))}
              className={cn(
                "min-h-10 cursor-pointer rounded-lg text-sm focus-visible:outline-2 focus-visible:outline-ring disabled:cursor-not-allowed disabled:opacity-30 aria-disabled:cursor-not-allowed data-disabled:cursor-not-allowed",
                day.month !== start.month && "text-muted-foreground",
                date === value
                  ? "bg-primary text-primary-foreground"
                  : range && value >= range.from && value <= range.to
                    ? "bg-primary/15 text-foreground"
                    : "hover:bg-accent",
              )}
              onClick={() => onChange(value)}
            >
              {day.day}
            </button>
          );
        })}
      </div>
      {showInput && (
        <Field label={labels.date}>
          <input
            type="date"
            className={fieldClass}
            value={date}
            min={minDate}
            onChange={(e) => {
              if (/^\d{4}-\d{2}-\d{2}$/.test(e.target.value)) {
                onChange(e.target.value);
                setMonth(Temporal.PlainDate.from(e.target.value).with({ day: 1 }).toString());
              }
            }}
          />
        </Field>
      )}
    </div>
  );
}

export function StayDatePicker({
  arrival,
  departure,
  onChange,
  minNights,
  labels,
  locale,
}: {
  arrival: string;
  departure: string;
  onChange: (arrival: string, departure: string) => void;
  minNights: number;
  labels: ReservationLabels;
  locale: string;
}) {
  const [endpoint, setEndpoint] = useState<"arrival" | "departure">("arrival");
  const departureInput = useRef<HTMLInputElement>(null);
  const choose = (value: string, part = endpoint) => {
    if (part === "arrival") {
      const minimum = Temporal.PlainDate.from(value).add({ days: minNights }).toString();
      onChange(value, departure < minimum ? minimum : departure);
      setEndpoint("departure");
    } else onChange(arrival, value);
  };
  return (
    <div className="space-y-4">
      <div className="grid gap-3 sm:grid-cols-2">
        {(["arrival", "departure"] as const).map((part) => (
          <Field key={part} label={part === "arrival" ? labels.arrivalDate : labels.departureDate}>
            <input
              type="date"
              required
              className={fieldClass}
              ref={part === "departure" ? departureInput : undefined}
              value={part === "arrival" ? arrival : departure}
              min={
                part === "departure"
                  ? Temporal.PlainDate.from(arrival).add({ days: minNights }).toString()
                  : undefined
              }
              onFocus={() => setEndpoint(part)}
              onChange={(event) => {
                if (event.target.value) choose(event.target.value, part);
              }}
            />
          </Field>
        ))}
      </div>
      <div className="flex flex-wrap gap-2">
        <button
          type="button"
          className={endpoint === "arrival" ? primaryClass : buttonClass}
          aria-pressed={endpoint === "arrival"}
          onClick={() => setEndpoint("arrival")}
        >
          {labels.arrivalDate}
        </button>
        <button
          type="button"
          className={endpoint === "departure" ? primaryClass : buttonClass}
          aria-pressed={endpoint === "departure"}
          onClick={() => setEndpoint("departure")}
        >
          {labels.departureDate}
        </button>
      </div>
      <DatePicker
        key={endpoint + (endpoint === "arrival" ? arrival.slice(0, 7) : departure.slice(0, 7))}
        date={endpoint === "arrival" ? arrival : departure}
        onChange={(value) => {
          choose(value);
          if (endpoint === "arrival") departureInput.current?.focus();
        }}
        labels={labels}
        locale={locale}
        minDate={
          endpoint === "departure"
            ? Temporal.PlainDate.from(arrival).add({ days: minNights }).toString()
            : undefined
        }
        range={{ from: arrival, to: departure }}
        showInput={false}
      />
    </div>
  );
}

export function SlotPicker({
  slots,
  selected,
  onChange,
  locale,
  zone,
  labels,
}: {
  slots: ReservationSlot[];
  selected: string;
  onChange: (value: string) => void;
  locale: string;
  zone: string;
  labels: ReservationLabels;
}) {
  return slots.length ? (
    <fieldset className="space-y-3">
      <legend className="mb-2 text-sm font-medium">{labels.time}</legend>
      <div className="grid grid-cols-2 gap-2 sm:grid-cols-3">
        {slots.map((slot) => (
          <button
            key={slot.startsAt}
            type="button"
            className={selected === slot.startsAt ? primaryClass : buttonClass}
            aria-pressed={selected === slot.startsAt}
            onClick={() => onChange(slot.startsAt)}
          >
            {formatTime(slot.startsAt, locale, zone)}
          </button>
        ))}
      </div>
    </fieldset>
  ) : (
    <output className="block text-sm text-muted-foreground">{labels.emptySlots}</output>
  );
}

"use client";

import { useMemo, useState } from "react";
import { Temporal } from "temporal-polyfill";

import type { ReservationLabels } from "@/components/plugins/reservations/labels";
import { localDate } from "@/components/plugins/reservations/model";
import type { ReservationAdminRecord } from "@/components/plugins/reservations/types";
import { cn } from "@/components/utils/cn";

export interface ReservationYearViewProps {
  start: string;
  reservations: ReservationAdminRecord[];
  locale: string;
  timeZone: string;
  labels: ReservationLabels;
  onSelectDate: (date: string) => void;
}

export function ReservationYearView({
  start,
  reservations,
  locale,
  timeZone,
  labels,
  onSelectDate,
}: ReservationYearViewProps) {
  const firstMonth = Temporal.PlainDate.from(start).with({ day: 1 });
  const today = localDate(new Date().toISOString(), timeZone);
  const [focused, setFocused] = useState(() =>
    today >= start && today < firstMonth.add({ years: 1 }).toString() ? today : start,
  );
  const counts = useMemo(() => {
    const days = new Map<string, number>();
    for (const reservation of reservations) {
      let date = Temporal.PlainDate.from(localDate(reservation.startsAt, timeZone));
      const last =
        reservation.mode === "stay"
          ? localDate(new Date(Date.parse(reservation.endsAt) - 1).toISOString(), timeZone)
          : date.toString();
      while (date.toString() <= last) {
        const key = date.toString();
        days.set(key, (days.get(key) ?? 0) + 1);
        date = date.add({ days: 1 });
      }
    }
    return days;
  }, [reservations, timeZone]);
  const monthFormat = new Intl.DateTimeFormat(locale, {
    month: "long",
    year: "numeric",
    timeZone: "UTC",
  });
  const dateFormat = new Intl.DateTimeFormat(locale, { dateStyle: "full", timeZone: "UTC" });
  const numberFormat = new Intl.NumberFormat(locale);
  return (
    <div className="space-y-3">
      <p className="text-sm text-muted-foreground">{labels.yearHelp}</p>
      <div className="max-w-full overflow-x-auto rounded-lg border border-border">
        <table className="w-full min-w-[88rem] table-fixed border-separate border-spacing-0 text-sm">
          <caption className="sr-only">{labels.year}</caption>
          <colgroup>
            <col className="w-40" />
            {Array.from({ length: 31 }, (_, i) => (
              <col key={i} />
            ))}
          </colgroup>
          <tbody>
            {Array.from({ length: 12 }, (_, index) => {
              const month = firstMonth.add({ months: index });
              return (
                <tr key={month.toString()}>
                  <th
                    scope="row"
                    className="sticky left-0 z-10 border-r border-b border-border bg-background px-3 py-2 text-left font-medium"
                  >
                    {monthFormat.format(new Date(`${month.toString()}T12:00:00Z`))}
                  </th>
                  {Array.from({ length: 31 }, (_, i) => {
                    if (i >= month.daysInMonth)
                      return (
                        <td
                          key={i}
                          aria-hidden="true"
                          className="border-r border-b border-border bg-muted"
                        />
                      );
                    const day = month.with({ day: i + 1 });
                    const date = day.toString();
                    const count = counts.get(date) ?? 0;
                    return (
                      <td key={i} className="border-r border-b border-border p-0">
                        <button
                          type="button"
                          data-date={date}
                          tabIndex={focused === date ? 0 : -1}
                          aria-current={today === date ? "date" : undefined}
                          aria-label={`${dateFormat.format(new Date(`${date}T12:00:00Z`))} · ${labels.calendar}: ${numberFormat.format(count)}`}
                          className={cn(
                            "flex min-h-10 w-full cursor-pointer scroll-mr-1 scroll-ml-40 flex-col items-center justify-center gap-0.5 px-1 py-1 hover:bg-accent focus-visible:relative focus-visible:z-20 focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-ring disabled:cursor-not-allowed aria-disabled:cursor-not-allowed data-disabled:cursor-not-allowed",
                            day.dayOfWeek > 5 && "bg-muted/50 text-muted-foreground",
                            count > 0 && "bg-accent text-accent-foreground",
                            today === date && "ring-2 ring-primary ring-inset",
                          )}
                          onFocus={(event) => {
                            setFocused(date);
                            event.currentTarget.scrollIntoView({
                              block: "nearest",
                              inline: "nearest",
                            });
                          }}
                          onClick={() => onSelectDate(date)}
                          onKeyDown={(event) => {
                            const next =
                              event.key === "ArrowRight"
                                ? day.add({ days: 1 })
                                : event.key === "ArrowLeft"
                                  ? day.subtract({ days: 1 })
                                  : event.key === "ArrowDown"
                                    ? day.add({ months: 1 })
                                    : event.key === "ArrowUp"
                                      ? day.subtract({ months: 1 })
                                      : event.key === "Home"
                                        ? day.with({ day: 1 })
                                        : event.key === "End"
                                          ? day.with({ day: day.daysInMonth })
                                          : null;
                            if (next) {
                              event.preventDefault();
                              event.currentTarget
                                .closest("table")
                                ?.querySelector<HTMLButtonElement>(
                                  `button[data-date="${next.toString()}"]`,
                                )
                                ?.focus();
                            }
                          }}
                        >
                          <span className="leading-4">{String(day.day).padStart(2, "0")}</span>
                          <span
                            aria-hidden="true"
                            className={cn(
                              "min-h-3 min-w-4 rounded-full px-1 text-[10px] leading-3",
                              count > 0 && "bg-primary font-semibold text-primary-foreground",
                            )}
                          >
                            {count > 0 ? numberFormat.format(count) : ""}
                          </span>
                        </button>
                      </td>
                    );
                  })}
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}
